Object.assign(AUDIO_CAST_MAP,{"paco:Buenos días, ¿qué va a tomar?": "assets/audio/story167-0dd99b93eed84173edbe.mp3", "luna:Buenos días. Un café con leche, por favor.": "assets/audio/story167-2b2c33e49b00bdc25a7d.mp3", "paco:¿Algo más? Tenemos cruasanes.": "assets/audio/story167-6fa1c727f47a2fd3cd0c.mp3", "luna:Sí, un cruasán también.": "assets/audio/story167-a723e15f613e0542813f.mp3", "paco:¿Para aquí o para llevar?": "assets/audio/story167-4ceb1791034147c20ed1.mp3", "luna:Para llevar, gracias.": "assets/audio/story167-ddfd8d36c700ad9df01d.mp3", "paco:Son tres euros con cincuenta.": "assets/audio/story167-001250bb1b0f443ebd3e.mp3", "luna:Aquí tiene. ¡Que tenga buen día!": "assets/audio/story167-318d0082fab564323b72.mp3", "luna:Perdone, ¿dónde está el metro?": "assets/audio/story167-2b949f14ec352b5240db.mp3", "paco:¿El metro? Siga todo recto.": "assets/audio/story167-82898cd1f68585e90ce5.mp3", "luna:¿Todo recto?": "assets/audio/story167-2be9dcc068ce6e06d0b0.mp3", "paco:Sí, y luego gire a la izquierda.": "assets/audio/story167-9b4b82392ff46a289492.mp3", "luna:¿Está lejos?": "assets/audio/story167-d402fe42aa54f243f33d.mp3", "paco:No, está muy cerca. Dos minutos.": "assets/audio/story167-05e01858f0d09af7e5ac.mp3", "luna:Muchas gracias.": "assets/audio/story167-389ac6b09b323bcde11b.mp3", "paco:De nada. Adiós.": "assets/audio/story167-0bae38057b2223590704.mp3", "luna:Hola, ¿a cuánto están los plátanos?": "assets/audio/story167-b371d88d6b63b3ae3e93.mp3", "paco:A dos euros el kilo.": "assets/audio/story167-8ec0f28503ec3f518762.mp3", "luna:Vale. ¿Y las manzanas?": "assets/audio/story167-42cc4b763b4a9b2aad22.mp3", "paco:Las manzanas, a uno ochenta.": "assets/audio/story167-bfb5e0298004ad3f42b4.mp3", "luna:Quiero un kilo de plátanos, por favor.": "assets/audio/story167-15990f1d8d1d0043ee22.mp3", "paco:¿Algo más?": "assets/audio/story167-0b4c761ca309c0e2373e.mp3", "luna:No, nada más. ¿Cuánto es?": "assets/audio/story167-4cc606a817711d098a1f.mp3", "paco:Dos euros.": "assets/audio/story167-08c036150a880cc712e5.mp3", "luna:Tome. Gracias, adiós.": "assets/audio/story167-d81e882dc5b91278824a.mp3", "luna:¡Hola! ¿Eres nuevo en el edificio?": "assets/audio/story167-ee085de1b5a522bd2015.mp3", "paco:Sí, me llamo Paco. Vivo en el tercero.": "assets/audio/story167-b45cb6e006a0fa656d65.mp3", "luna:Encantada, Paco. Yo soy Luna, del segundo.": "assets/audio/story167-b10681121b38b17c7c37.mp3", "paco:Encantado, Luna. ¿Llevas mucho tiempo aquí?": "assets/audio/story167-edace7d788fdeef89d99.mp3", "luna:Sí, dos años.": "assets/audio/story167-ad7a97f1e8dc57e0f207.mp3", "paco:¿Y trabajas cerca?": "assets/audio/story167-4bf10258d4378dff7efc.mp3", "luna:Sí, trabajo en una farmacia, al lado del metro.": "assets/audio/story167-e2e8e4664f4f0ea08afa.mp3", "paco:¡Qué bien! Hasta luego, Luna.": "assets/audio/story167-08105788635679b39214.mp3", "luna:Hasta luego. ¡Bienvenido!": "assets/audio/story167-5996eae87d77a263c730.mp3", "luna:Buenos días. Vengo a recoger un paquete.": "assets/audio/story167-2782364be4a73c2c1ea9.mp3", "paco:Buenos días. ¿Tiene el código de seguimiento?": "assets/audio/story167-e596cff9045d2dac4127.mp3", "luna:Sí, mire. Me llegó un mensaje ayer.": "assets/audio/story167-72685dea4717434af51e.mp3", "paco:Gracias... Mmm, qué raro. Este paquete no está aquí.": "assets/audio/story167-c740b082582bcd0879af.mp3", "luna:¿Cómo que no está? El mensaje dice que es esta tienda.": "assets/audio/story167-dcc6bc597ceb791a67fa.mp3", "paco:Ya lo veo, pero mire la dirección: es la otra sucursal, la de la calle Mayor.": "assets/audio/story167-f78aab073ee5e0943c9f.mp3", "luna:¡Ay, es verdad! No leí bien el mensaje.": "assets/audio/story167-21c330e4a8ec6cc6e08b.mp3", "paco:No pasa nada, le pasa a mucha gente. Las dos sucursales tienen el mismo nombre, por eso pasa.": "assets/audio/story167-68f60df172542da61364.mp3", "luna:¿Y puedo recogerlo allí hoy?": "assets/audio/story167-90e79a2e0c64da5eee88.mp3", "paco:Sí, claro. Cierran a las nueve. Voy a llamar a la otra sucursal para avisar.": "assets/audio/story167-dc8a0274e8586e5e211d.mp3", "luna:Muy amable. ¿Sabe si hay un metro cerca?": "assets/audio/story167-c20b7108f2ef3a7d3ff8.mp3", "paco:Sí, la estación de Ópera está a cinco minutos a pie.": "assets/audio/story167-3c31089cc2e0ab8e0b72.mp3", "luna:Perfecto. Entonces paso por allí después del trabajo.": "assets/audio/story167-f71b3d180497e08dfeb6.mp3", "paco:De acuerdo. ¡Que tenga buen día!": "assets/audio/story167-84a671af35636dc9e28a.mp3", "luna:Gracias, igualmente.": "assets/audio/story167-66b3a0db855489f99e43.mp3", "paco:Clínica Sol, buenos días.": "assets/audio/story167-e1ea96e6afb1f0b14349.mp3", "luna:Buenos días. Tengo una cita mañana y quiero cambiarla.": "assets/audio/story167-b2c163b7c168d9c825f4.mp3", "paco:Muy bien. ¿A qué hora es su cita?": "assets/audio/story167-a6552eb3bc593ea584d7.mp3", "luna:A las diez, con la doctora Ruiz.": "assets/audio/story167-2b1ca92444e410af5e7b.mp3", "paco:Sí, aquí está. ¿Qué día le viene bien?": "assets/audio/story167-affc29874de1ad272b64.mp3", "luna:¿Es posible el jueves por la tarde?": "assets/audio/story167-1b7ad56f28960af4c9fa.mp3", "paco:El jueves... hay un hueco libre a las cinco y media.": "assets/audio/story167-1e6c0cd4000ac8c0f963.mp3", "luna:Perfecto, me viene muy bien.": "assets/audio/story167-48944c69c6f9ffe1b4c8.mp3", "paco:Entonces, el jueves a las cinco y media con la doctora Ruiz.": "assets/audio/story167-182d13b68d5bfde237e2.mp3", "luna:Muy bien. ¿Tengo que traer algo?": "assets/audio/story167-1d23ead88c6d0cdc3cd4.mp3", "paco:Solo su tarjeta sanitaria.": "assets/audio/story167-02acfcf90234c4e1ffe4.mp3", "luna:De acuerdo. Muchas gracias.": "assets/audio/story167-454236e70722df3ba430.mp3", "paco:A usted. Hasta el jueves.": "assets/audio/story167-05c6947248e45148c827.mp3", "paco:¡Qué mala suerte! He perdido el tren de las nueve.": "assets/audio/story167-6fd62eeacfbedcf55462.mp3", "luna:¿A qué hora ha llegado usted?": "assets/audio/story167-4ab46fa417dba87e3700.mp3", "paco:A las nueve y cinco. El autobús llegó tarde.": "assets/audio/story167-03d40cc294971bfbbf5e.mp3", "luna:Entiendo. ¿Adónde viaja?": "assets/audio/story167-204b58add8caeca183ad.mp3", "paco:A Valencia. Tengo una reunión a las doce.": "assets/audio/story167-5431fb33ddb78147ad4e.mp3", "luna:Hay otro tren a las nueve y media. Llega a las once y veinte.": "assets/audio/story167-c1ea9ad1c7d86e7ca1f8.mp3", "paco:¿Y llego a tiempo para la reunión?": "assets/audio/story167-d65c6cba0dfe494e6ab4.mp3", "luna:Sí, si sale de la estación rápido. Hay taxis en la puerta.": "assets/audio/story167-d7699de852e910a8dbc5.mp3", "paco:Vale, quiero un billete para ese tren.": "assets/audio/story167-0eba592179a3748e1bf4.mp3", "luna:¿Su billete anterior era flexible?": "assets/audio/story167-d5dc1fa3aec7f5f6ba9d.mp3", "paco:Sí, era flexible.": "assets/audio/story167-c69979a74f9155866f53.mp3", "luna:Entonces el cambio es gratis. Aquí tiene su nuevo billete.": "assets/audio/story167-788aa302b1f02f881bad.mp3", "paco:¡Muchas gracias! Me ha salvado.": "assets/audio/story167-b5426be7b982f5ab7dd4.mp3", "luna:Bueno, ¿qué te ha parecido el piso?": "assets/audio/story167-f269d3fc85b256b2e7d6.mp3", "paco:A mí me ha encantado. Es grande y tiene mucha luz.": "assets/audio/story167-a075a11449a45a0cf100.mp3", "luna:Sí, es verdad, pero está un poco lejos del centro.": "assets/audio/story167-cacd4d6f162793596a39.mp3", "paco:Ya, pero por eso es más barata. Con lo que ahorramos podemos pagar el transporte.": "assets/audio/story167-4f2a7aaf4069f5974df4.mp3", "luna:No sé... yo tardaría cuarenta minutos en llegar al trabajo.": "assets/audio/story167-d317479f59e7241c7ab7.mp3", "paco:¿Y si nos mudamos y lo probamos unos meses? El contrato es de once meses.": "assets/audio/story167-818d54342772292fb3d6.mp3", "luna:Es que también me preocupa la cocina. Es muy pequeña.": "assets/audio/story167-fcf5a1f868556d00c28e.mp3", "paco:Hombre, pero tú casi no cocinas entre semana.": "assets/audio/story167-95b880caa5e87b177ffd.mp3", "luna:¡Eso no es verdad! Cocino casi todos los días.": "assets/audio/story167-f2ed0016e7e35741c1f2.mp3", "paco:Vale, vale, tienes razón. Entonces, ¿qué hacemos?": "assets/audio/story167-21a7985aeac6a47cb7f5.mp3", "luna:Mira, me gusta el piso, pero quiero ver otro que hay cerca del metro. Si no nos convence, nos quedamos con este.": "assets/audio/story167-0bca099ed5cd01a00385.mp3", "paco:Me parece justo. Pero hay que decidir rápido, que el dueño dijo que tiene más interesados.": "assets/audio/story167-8e9e010193281a6919bb.mp3", "luna:Vale. Mañana vemos el otro y por la noche decidimos.": "assets/audio/story167-35993eec0881a88bab2f.mp3", "paco:Trato hecho.": "assets/audio/story167-a847043e3bd323150530.mp3", "paco:Oye, Luna, ¿has comprado ya el regalo para el sábado?": "assets/audio/story167-81947396edb89a8dba37.mp3", "luna:¿Para el sábado? La fiesta de Marta es el domingo.": "assets/audio/story167-0a64f6141e988b1406c8.mp3", "paco:No, mujer, es el sábado. Me lo dijo ella misma.": "assets/audio/story167-427f1712b4d9042a4545.mp3", "luna:Pues a mí me mandó un mensaje que ponía: «el domingo a las ocho».": "assets/audio/story167-03f6ecda1f68cc0da2ce.mp3", "paco:Qué raro... A ver, enséñame el mensaje.": "assets/audio/story167-f45d48028288514b7934.mp3", "luna:Mira. «El domingo a las ocho en mi casa».": "assets/audio/story167-0346c51258e6c2e9a874.mp3", "paco:¡Ah, ya entiendo! Marta cambió el día. El sábado era el plan original.": "assets/audio/story167-8c74df4e1e34aac04287.mp3", "luna:¿Y por qué no te avisó a ti?": "assets/audio/story167-07c620d0f2ae7d34b56c.mp3", "paco:Pues... porque yo estaba sin móvil toda la semana, ¿no te acuerdas?": "assets/audio/story167-8f4ee589a45df8401e33.mp3", "luna:¡Es verdad! Se te rompió la pantalla.": "assets/audio/story167-24dfcd66acf6d62526cd.mp3", "paco:Eso es. Menos mal que me lo has dicho, porque yo iba a aparecer allí el sábado con el regalo.": "assets/audio/story167-2ab600510163b654369f.mp3", "luna:Imagina la cara de Marta. «Paco, la fiesta es mañana».": "assets/audio/story167-7d46913e2d7fad9c6bab.mp3", "paco:Ja, ja. Bueno, el sábado entonces salimos nosotros, ¿no? Ya que estamos libres.": "assets/audio/story167-520951a4edaeefc1203f.mp3", "luna:¡Buena idea! Así no perdemos el plan.": "assets/audio/story167-5c8ecdcf5bc6da3d87d3.mp3", "luna:Paco, tengo que contarte algo. Me han ofrecido otro trabajo.": "assets/audio/story167-6d9292792dc24e693b76.mp3", "paco:¡Anda! ¿Dónde?": "assets/audio/story167-423481302fea7b1a81f6.mp3", "luna:En una empresa grande, en las afueras. Pagan un veinte por ciento más.": "assets/audio/story167-3d1a533c90b35d96d626.mp3", "paco:¡Un veinte por ciento! Eso está muy bien.": "assets/audio/story167-285d16603ebf40ebba63.mp3", "luna:Sí, pero tardaría una hora en llegar. Ahora tardo diez minutos andando.": "assets/audio/story167-dff76beb5eafec85105c.mp3", "paco:Buf, eso son dos horas al día. ¿Y el ambiente? ¿Has hablado con alguien de allí?": "assets/audio/story167-5ccff39bb1d1ac0f41cf.mp3", "luna:Sí, he hablado con una chica que trabaja allí. Dice que el ambiente es bueno, pero hay mucha presión.": "assets/audio/story167-f69156a33a4519b27630.mp3", "paco:¿Y en tu trabajo actual estás a gusto?": "assets/audio/story167-d26f01e7c70a5ea75a4b.mp3", "luna:La verdad es que sí. Me llevo bien con todos y el horario es flexible.": "assets/audio/story167-43e5d3df3fd1f31f395d.mp3", "paco:Pues yo creo que tienes que pensar qué es más importante para ti ahora: el dinero o la tranquilidad.": "assets/audio/story167-98dcba3792cdde0f40de.mp3", "luna:Es que necesito ahorrar. Quiero hacer un máster el año que viene.": "assets/audio/story167-47f5ca9fa3ef12ac8e62.mp3", "paco:Ah, eso cambia las cosas. Si ahorras ese veinte por ciento durante un año, ¿te llega?": "assets/audio/story167-ca62afead305bb63e04f.mp3", "luna:Sí, me llega justo.": "assets/audio/story167-12e38ed41863d11a3e96.mp3", "paco:Entonces yo lo aceptaría. Aguanta un año, ahorra, y luego ya veremos.": "assets/audio/story167-0ab0c9d1b3fdcfe1c9c5.mp3", "luna:Tienes razón. Mañana les respondo que sí.": "assets/audio/story167-fe67d9a98cab86fd4b0d.mp3", "paco:Buenas. Se me ha roto la pantalla del móvil. ¿Tiene arreglo?": "assets/audio/story167-933c28b0891e48d388a5.mp3", "luna:A ver... Sí, se puede cambiar. ¿Qué modelo es?": "assets/audio/story167-ee6c86064fa3a41bffbf.mp3", "paco:Es un modelo de hace cuatro años.": "assets/audio/story167-ba010dcc4da0900c3f98.mp3", "luna:Mire, la pantalla cuesta ochenta euros, más veinte de mano de obra.": "assets/audio/story167-67620ca05952e2bb5e05.mp3", "paco:Cien euros... no sé si merece la pena. El móvil ya es viejo.": "assets/audio/story167-79b85aa32dc07062add3.mp3", "luna:Entiendo. Depende. ¿Le funciona bien todo lo demás?": "assets/audio/story167-88a70cf4711d0fd33df0.mp3", "paco:La batería dura poco, pero lo demás va bien.": "assets/audio/story167-b1150952790963b0d8e1.mp3", "luna:Pues otra cosa: la batería de este modelo ya no se encuentra fácil. Si se la cambiamos dentro de unos meses, será otro gasto.": "assets/audio/story167-c96f96b967974c187a9f.mp3", "paco:O sea, que si lo arreglo ahora, en unos meses igual tengo otro problema.": "assets/audio/story167-4810438da6963c07cbd4.mp3", "luna:Exacto. Yo le diría que se comprara uno nuevo. Con cien euros más lo que ahorra, tiene un móvil mejor.": "assets/audio/story167-e1a401694ae077199f52.mp3", "paco:¿Y no me estará vendiendo la moto?": "assets/audio/story167-2d2e165641ce86aa6f95.mp3", "luna:No, si aquí solo reparamos, no vendemos móviles. Se lo digo porque es lo que yo haría.": "assets/audio/story167-bda8287cf673b6161d29.mp3", "paco:Vale, me ha convencido. Entonces no hace falta el arreglo.": "assets/audio/story167-f64d8b7c51009a8b5347.mp3", "luna:Un consejo: antes de tirar el viejo, pase las fotos al ordenador.": "assets/audio/story167-8b73c748018297ac1234.mp3", "paco:¡Buena idea! Gracias por la honestidad.": "assets/audio/story167-d863be156e48535e1473.mp3", "luna:Buenos días. ¿En qué puedo ayudarle?": "assets/audio/story167-ed586848cce8d33cd032.mp3", "paco:Mire, este mes la factura me ha llegado del doble de lo normal, y no entiendo por qué.": "assets/audio/story167-dfac2a9aca747d6e9736.mp3", "luna:Vamos a verlo. ¿Me da su número, por favor? ... Aquí está. Efectivamente, hay un cargo de datos internacionales.": "assets/audio/story167-d492221d6b408002e296.mp3", "paco:¿Datos internacionales? Si yo no he salido de España este año.": "assets/audio/story167-2cdb5b26295596db18d8.mp3", "luna:A veces el móvil se conecta a una red extranjera si vive cerca de la frontera. ¿Ha estado cerca de Portugal o Francia?": "assets/audio/story167-5e95f49a1e3348da05e6.mp3", "paco:Vivo en Madrid. Esto es un error, claramente.": "assets/audio/story167-a14e8a04f0f0010ca4be.mp3", "luna:Tiene razón, Madrid no tiene sentido. Le abro una reclamación ahora mismo y le devolvemos el importe en la próxima factura.": "assets/audio/story167-fdc062e5ddfad7d9dc53.mp3", "paco:¿En la próxima factura? Yo preferiría que me lo devolvieran ya. Es dinero que se me ha cobrado de más.": "assets/audio/story167-806c9b10c9f3878d14db.mp3", "luna:Lo entiendo, pero el sistema solo permite el abono en factura. Lo que sí puedo hacer es que se anote como prioridad, para que no se retrase.": "assets/audio/story167-ab9ee0190f3f8a11e189.mp3", "paco:Vale, pero quiero un número de referencia y algo por escrito.": "assets/audio/story167-718cb67827ed4091afd5.mp3", "luna:Por supuesto. Aquí tiene: es la referencia erre-cuatro-cero-dos-uno-cinco. Y le llegará un correo de confirmación hoy.": "assets/audio/story167-fc552f2e970355eec90d.mp3", "paco:De acuerdo. Y si la próxima factura llega sin el abono, ¿qué hago?": "assets/audio/story167-59b33a0b4f3a2fffbf96.mp3", "luna:Llame al número de atención y dé esa referencia. Con eso recuperan todo el trámite en un minuto.": "assets/audio/story167-ba07c7c7b1b0aaec89d4.mp3", "paco:Perfecto. Gracias por su ayuda.": "assets/audio/story167-901e952f9afefb5081eb.mp3", "luna:Paco, tenemos que hablar del proyecto. El cliente me ha llamado dos veces esta semana.": "assets/audio/story167-1ce7519fe6a2a0753616.mp3", "paco:Ya me lo imagino. Mira, el retraso no es por falta de trabajo, es que los cambios que pidió el cliente nos han llevado una semana entera.": "assets/audio/story167-c72ee0d8ef642d96170c.mp3", "luna:Lo sé, y por eso quiero que lo veamos juntos. Si entregáramos lo que hay ahora, ¿qué faltaría?": "assets/audio/story167-31303e931026be9a13b7.mp3", "paco:Faltaría la parte de informes y las pruebas finales. Sin eso, el cliente no puede usar el sistema solo.": "assets/audio/story167-4219dbeacaac928d4cbd.mp3", "luna:Vale. ¿Cuánto tiempo necesitas de verdad? No quiero fechas bonitas, quiero fechas reales.": "assets/audio/story167-e6b166b77cfb925c92d4.mp3", "paco:Si me quitas las reuniones de esta semana, termino los informes el jueves. Las pruebas, tres días laborables más.": "assets/audio/story167-65e81559990e00e3ae7b.mp3", "luna:O sea, el martes de la semana que viene.": "assets/audio/story167-f80cafd28f25bdb7918b.mp3", "paco:El martes, sí. Y si surge algún imprevisto, el miércoles como mucho.": "assets/audio/story167-7cf76b6a57fbaecc0035.mp3", "luna:Entonces le digo al cliente miércoles. Prefiero dar un día más y cumplir, que dar el martes y fallar.": "assets/audio/story167-e144384e7abe83e50aea.mp3", "paco:De acuerdo. Y otra cosa: estaría bien que le explicaras al cliente que los cambios tienen un coste de tiempo, para la próxima.": "assets/audio/story167-256fbf0ab5dc81e2516c.mp3", "luna:Tienes razón. Voy a preparar un resumen de los cambios y sus fechas, así lo ve claro.": "assets/audio/story167-b43b01be8d1ddcbdb30b.mp3", "paco:Perfecto. Entonces, sin reuniones esta semana, ¿eh?": "assets/audio/story167-1ca00fa64b4a8276b75b.mp3", "luna:Sin reuniones. Pero el jueves quiero ver los informes terminados.": "assets/audio/story167-0921ec21cf7153d53119.mp3", "paco:Recepción, buenas tardes.": "assets/audio/story167-3be4b0cefbce9b415ecd.mp3", "luna:Buenas tardes. Tengo una reserva para este fin de semana y necesito cancelarla. Me ha surgido un problema familiar.": "assets/audio/story167-235b467d8a032ebdf0b2.mp3", "paco:Lo siento mucho. Déjeme ver... Sí, aquí está. Le comento que su tarifa es no reembolsable, se lo indicaba la confirmación.": "assets/audio/story167-c3277dc9f86489de7dc8.mp3", "luna:Sí, lo sé, lo vi. Pero pensé que, siendo un problema familiar, podrían hacer una excepción.": "assets/audio/story167-aad99450ecc09ba5c67d.mp3", "paco:Entiendo perfectamente su situación. Mire, una devolución completa no puedo autorizarla yo, pero hay una opción que igual le interesa.": "assets/audio/story167-5458052137bf81c12a44.mp3", "luna:Dígame.": "assets/audio/story167-6cf81620900b98e36db3.mp3", "paco:Puedo cambiarle la reserva a cualquier fin de semana de los próximos seis meses, sin coste adicional. Así no pierde el dinero.": "assets/audio/story167-f156bad332b0d96fe360.mp3", "luna:¿Y si el fin de semana que elija es más caro?": "assets/audio/story167-b2bc1ff07dc1919deaef.mp3", "paco:Pagaría solo la diferencia. Si es más barato, se lo dejamos como crédito para el desayuno o el parking.": "assets/audio/story167-c52588161aeeeb48b3ad.mp3", "luna:Hmm. ¿Y no hay manera de que me devuelvan al menos la mitad? Prefiero el dinero, la verdad, porque no sé cuándo podré viajar.": "assets/audio/story167-8e543af14cff0402c2dd.mp3", "paco:Le voy a ser sincero: con esa tarifa, la mitad tampoco está en mi mano. Lo que sí puedo hacer es anotar su caso y que la dirección lo revise mañana. No le prometo nada, pero se lo paso con buena recomendación.": "assets/audio/story167-1f1766c6b6794ee51216.mp3", "luna:Vale. Hágalo, por favor. ¿Y si dicen que no, me queda la opción del cambio de fechas?": "assets/audio/story167-4f2a80d00921481e209e.mp3", "paco:Exacto, esa opción sigue disponible durante seis meses. Le llamo mañana antes de las doce con la respuesta.": "assets/audio/story167-7bab3f5280248259cd71.mp3", "luna:De acuerdo. Gracias por la claridad, de verdad.": "assets/audio/story167-253aa4f886ae15a081e5.mp3", "luna:Su experiencia es muy interesante, pero me llama la atención una cosa: hay un año entero sin trabajar entre sus dos últimos empleos. ¿Puede contarme qué pasó?": "assets/audio/story167-ef9f2fee155bdcd9e5ca.mp3", "paco:Claro. La empresa donde trabajaba cerró y me quedé sin empleo. Los primeros meses busqué trabajo sin parar, pero el sector estaba parado.": "assets/audio/story167-8932162efafee18dffa0.mp3", "luna:¿Y el resto del año?": "assets/audio/story167-a54f719009a24a97ba17.mp3", "paco:Mi madre enfermó y decidí cuidarla. Podía permitírmelo unos meses, y era más importante para mí que aceptar cualquier trabajo rápido.": "assets/audio/story167-1d27b3b09e09e1cff92b.mp3", "luna:Entiendo. Algunos entrevistadores verían eso como un riesgo: que usted deje el trabajo si surge algo personal.": "assets/audio/story167-5144311cd6654c13607f.mp3", "paco:Yo lo veo al revés: volví en cuanto mi madre mejoró, y en mi trabajo actual pasé cuatro años sin faltar apenas. Sé separar las cosas, pero también sé qué es lo importante.": "assets/audio/story167-77e97783da340078819c.mp3", "luna:Bien dicho. Otra pregunta: ¿por qué quiere dejar su trabajo actual?": "assets/audio/story167-f38db6a502ba25bb798d.mp3", "paco:Porque he llegado al techo. Aprendí todo lo que podía aprender allí, y su empresa trabaja en proyectos que allí no existen.": "assets/audio/story167-a14679841ec976d35da2.mp3", "luna:¿Y si le ofrecieran allí más dinero para quedarse?": "assets/audio/story167-af0f5bc8d73b89806389.mp3", "paco:Le seré sincero: el dinero importa, pero si fuera solo eso, ya me habría ido a cualquier otro sitio. Lo que busco es crecer, y eso aquí lo veo claro.": "assets/audio/story167-6ae25214a6eb27a94662.mp3", "luna:Muy bien. Nosotros también vamos a ser sinceros con usted: hay otros dos candidatos. Le llamaremos el viernes, sea cual sea la decisión.": "assets/audio/story167-a8916611b918817a14e7.mp3", "paco:Se lo agradezco. Prefiero un no claro a semanas de espera.": "assets/audio/story167-ebb06a155a4645e75b36.mp3", "paco:Buenas noches, Luna. Perdona la hora.": "assets/audio/story167-81e8245b9aa03410ffc2.mp3", "luna:Hola, Paco. ¿Pasa algo?": "assets/audio/story167-5b5ac04546e3223202ce.mp3", "paco:No es nada grave, pero... la música se oye bastante en mi salón. Tengo una reunión temprano mañana.": "assets/audio/story167-508362de7328485272f7.mp3", "luna:Ay, lo siento, no me había dado cuenta de que se oía tanto. Es el cumpleaños de mi hermana, ya ves.": "assets/audio/story167-33b80c4cde20f95eaa2f.mp3", "paco:Claro, claro, y ni se me pasa por la cabeza pedirte que cortes la fiesta. Ahora bien, si la bajaras un poco a partir de las doce, te lo agradecería de verdad.": "assets/audio/story167-f5f287246494b1a69dfa.mp3", "luna:Hecho. Y perdona que te lo diga, pero la última vez que tuviste invitados tú, yo no dije nada, ¿eh?": "assets/audio/story167-c859cd18e6ee020a183c.mp3", "paco:Tienes toda la razón, y te lo agradezco. Por eso vengo yo primero y en buen plan, en vez de llamar a la policía como haría otro.": "assets/audio/story167-63f7d361123ed6c7d015.mp3", "luna:Y yo te agradezco que vengas tú y no tu mujer, que la última vez casi me grita por el buzón.": "assets/audio/story167-bbb8c7d158d334fc176d.mp3", "paco:Ja, ja. Bueno, cada uno tiene su carácter. Entonces, ¿a las doce?": "assets/audio/story167-5fab62cfabfde05a1403.mp3", "luna:A las doce bajo la música y, para que puedas dormir, a la una apagamos del todo. Te invito a un trozo de tarta, por cierto.": "assets/audio/story167-25a7b7dc01249dd55a7c.mp3", "paco:Eso sí que es un buen final. Cinco minutos, que me quito el pijama.": "assets/audio/story167-776d036998cc9a5427db.mp3", "luna:Gracias a todos por venir. Como saben, el proyecto Andalucía arranca el mes que viene y hay que nombrar un responsable.": "assets/audio/story167-db6d26c145bff30f3e5c.mp3", "paco:Si me permites, Luna: yo llevo dos años con este cliente y conozco sus manías. Sería una pena perder ese conocimiento.": "assets/audio/story167-ad5d462c8b0f616ae24a.mp3", "luna:Claro, Paco, por muy valioso que sea ese conocimiento, y lo es, y contaremos contigo sí o sí, la pregunta es quién coordina.": "assets/audio/story167-6f34cdd092ae68909662.mp3", "paco:Pues eso es lo que digo: coordinar con un cliente que ya conoces es mucho más fácil que empezar de cero.": "assets/audio/story167-7f027ff0ab2ebc2a5f58.mp3", "luna:Totalmente de acuerdo. Aunque también hay que pensar en la carga: tú ya llevas el proyecto Norte y el mantenimiento. No querríamos quemarte.": "assets/audio/story167-bbfa62ac519c7430adc9.mp3", "paco:Te agradezco la preocupación, aunque prefiero decidir yo si puedo con más o no.": "assets/audio/story167-886d59a58d01fa169218.mp3", "luna:Por supuesto. Solo lo menciono porque el año pasado, cuando acumulaste tres proyectos, el cliente Norte se quejó de los tiempos.": "assets/audio/story167-2947c92fe2fa89aba9f6.mp3", "paco:Y precisamente por eso aprendí a organizarme mejor. Los errores de los que se aprende se llaman experiencia, ¿no?": "assets/audio/story167-3605ff8ba47d47434b31.mp3", "luna:Sin duda. Mira, te propongo esto: tú lideras la relación con el cliente, que es tu fuerte, y yo coordino la parte interna. Así el proyecto tiene lo mejor de cada uno.": "assets/audio/story167-0cda921e2d756a174d8e.mp3", "paco:Hmm. Oído. ¿Y a la hora de la verdad quién firma las entregas?": "assets/audio/story167-e03fefad2fc7c37c948e.mp3", "luna:Las firmamos los dos. Y si algún día hay que elegir, que elija el director. Pero sospecho que trabajando así no hará falta.": "assets/audio/story167-a516c0856c00b24d3f21.mp3", "paco:Trato hecho, entonces.": "assets/audio/story167-eaee0300ba6b84e22ac3.mp3", "luna:Por fin, ¿no? Te estaba esperando desde las ocho.": "assets/audio/story167-08bf1a4c50907d97f686.mp3", "paco:Son las ocho y cuarto, mujer, tampoco es para tanto.": "assets/audio/story167-ac01c9e94753910e7119.mp3", "luna:Paco, quedamos a las ocho. Y la semana pasada fueron veinte minutos, y la anterior, media hora. Como para no llevar la cuenta.": "assets/audio/story167-de6ad362a6f32d24be8a.mp3", "paco:Vale, ya veo por dónde vas. No es una queja, es un historial.": "assets/audio/story167-b7bc26517e60c9899c8e.mp3", "luna:Es que me fastidia, de verdad. No es por los quince minutos, es que me hace sentir que mi tiempo vale menos que el tuyo.": "assets/audio/story167-6c8b782c58331d7c611b.mp3", "paco:Venga, no exageres. Sabes que no pienso eso.": "assets/audio/story167-09fabe58512d0e770b9b.mp3", "luna:Lo que piensas no lo sé, lo que veo es que siempre llegas tarde y siempre hay una razón buena. El tráfico, una llamada, lo que sea.": "assets/audio/story167-ab4f9c91e34f7245013b.mp3", "paco:Uf. Vale. Puede que tengas razón en una cosa: yo siempre calculo el tiempo justo, y siempre pasa algo.": "assets/audio/story167-c121e2c1b3f1a459f172.mp3", "luna:Pues cuenta con un margen, como hago yo contigo desde hace años, por cierto.": "assets/audio/story167-46fe41aa638cc9be3aad.mp3", "paco:¿Cómo que como haces tú conmigo?": "assets/audio/story167-e1fc7cd3d9c91a34ff3b.mp3", "luna:Pues que cuando quedamos a las ocho, yo sé que llegarás a las ocho y cuarto, así que yo salgo de casa para llegar a las ocho y diez. Y hoy, mira, hoy llegué a las ocho en punto para comprobarlo. Y aquí estoy, esperando.": "assets/audio/story167-8ae1fd24407ebdad85e5.mp3", "paco:Es broma, ¿no? Llevas años llegando tarde a propósito para no esperarme.": "assets/audio/story167-43e8b1149e10c5750804.mp3", "luna:A propósito no, con conocimiento de causa. Que es distinto.": "assets/audio/story167-1c704e61756df573678d.mp3", "paco:Ja, ja. Está bien, me has ganado. Ocho en punto la próxima vez. Y si llego tarde, pago la cena.": "assets/audio/story167-c3e3b8eb32c1efe994bd.mp3", "luna:Apuntado. Y ya que estás, la de hoy también la pagas tú, que la espera ha sido larga.": "assets/audio/story167-87e7abbaa2076d0a9545.mp3", "paco:Negociadora nata. Venga, invito yo. Pero que conste que son las ocho y dieciséis.": "assets/audio/story167-59b6212240049017aa57.mp3", "paco:Luna, gracias por recibirme. Voy al grano: el contrato se renueva en dos meses y el precio de la zona ha subido mucho.": "assets/audio/story167-ee85dac0f133d1efb6ae.mp3", "luna:¿Cuánto piensa subirme?": "assets/audio/story167-4888a91d68edf0a8a944.mp3", "paco:Cincuenta euros al mes. Sigue siendo menos de lo que piden por pisos peores en esta calle.": "assets/audio/story167-a868f79b33147091a05e.mp3", "luna:Mire, Paco, yo también me he mirado los precios. Los pisos que usted dice llevan meses anunciados sin alquilarse. El precio que piden no es el precio que pagan.": "assets/audio/story167-ba1b62bbfa04d268f759.mp3", "paco:Puede ser, pero el mío se alquila mañana. Es una zona con mucha demanda.": "assets/audio/story167-29fe52aa2aea657b9ca2.mp3", "luna:Se alquila mañana, sí. Y luego usted tiene un inquilino nuevo que no conoce, que a saber si le paga a tiempo o le destroza la cocina. Yo llevo cuatro años pagando el día uno, y la caldera nueva se la pagué a medias, ¿se acuerda?": "assets/audio/story167-0deb21a6a5f9292761a5.mp3", "paco:Y se lo agradezco, de verdad. Pero usted entenderá que yo tampoco puedo regalar el dinero.": "assets/audio/story167-061bea4a4540d78dc427.mp3", "luna:No le pido que regale nada. Le pido que valore lo que tiene: un inquilino que no le da problemas y que cuida el piso como si fuera suyo. ¿Cuánto le cuesta un mes de piso vacío entre inquilino e inquilino? ¿Seiscientos euros? ¿Más?": "assets/audio/story167-b6017d10d628eecd6ea2.mp3", "paco:Ya veo que se lo ha pensado, y bien pensado.": "assets/audio/story167-1bc77a17b6d99e3f223d.mp3", "luna:Me lo he pensado porque me gusta esta casa y quiero quedarme. Por eso le propongo esto: veinticinco euros de subida ahora, y otros veinticinco dentro de un año si el mercado sigue subiendo. Usted cobra más, yo no me voy, y nadie busca pisos ni inquilinos.": "assets/audio/story167-aea38a65fe0b2ab65785.mp3", "paco:Treinta ahora y quince más dentro de un año.": "assets/audio/story167-67d8f5f977d468e4a001.mp3", "luna:Trato hecho. Y me lo manda por escrito esta semana, que luego los números bailan.": "assets/audio/story167-71c6de73f7a0b0a589be.mp3", "luna:Gracias por verme, Paco. Iré directa: quiero entender qué le faltó a mi candidatura para la dirección del departamento.": "assets/audio/story167-0f3babc5f99d9391ed71.mp3", "paco:Y yo te agradezco que preguntes en vez de hacer conjeturas. Mira, tu candidatura era excelente. La de Andrés también.": "assets/audio/story167-a1c9b7569a54b2285300.mp3", "luna:Eso lo entiendo. Lo que no entiendo es qué tenía la suya que no tuviera la mía, porque los resultados de mi equipo hablan solos.": "assets/audio/story167-da8b91c8783872216ac3.mp3", "paco:Y hablan, nadie lo discute. Pero el puesto no era solo de resultados. Andrés llevaba dos años en proyectos internacionales, y la dirección quiere abrir ese mercado.": "assets/audio/story167-e458a76a28e989c8730a.mp3", "luna:O sea que el criterio decisivo era un perfil que, por mucho que rindiera, yo no podía tener, porque nunca se me ofreció uno de esos proyectos.": "assets/audio/story167-88aede239d4f21952c75.mp3", "paco:Si te digo que no, te miento. Se le ofrecieron a él porque él los pidió. Ahí sí te digo algo: tú nunca pides nada. Rindes mejor que nadie y te quedas esperando a que lo noten.": "assets/audio/story167-4e3df7008b625427c137.mp3", "luna:¿Me está diciendo que el error fue no llamar a su puerta?": "assets/audio/story167-f4a9aa620d32233424ce.mp3", "paco:Te estoy diciendo que en esta empresa hay dos formas de ascender: ser imprescindible, que tú lo eres, y que se te vea pidiendo el siguiente escalón, que es lo que hizo Andrés. La próxima plaza se abrirá en un año, como mucho. Lo que hagas hasta entonces cuenta.": "assets/audio/story167-6e1deb61032dc7758a4f.mp3", "luna:Entonces pido formalmente el proyecto internacional que se está gestando. Y pido que conste en algún sitio que lo he pedido.": "assets/audio/story167-9621f4cfa05552072b9c.mp3", "paco:Consta desde hoy. Y una cosa más, ya que estamos siendo directos: si en un año no se abre nada, ¿qué harás?": "assets/audio/story167-ef79bdb3688b4edca63d.mp3", "luna:Le voy a ser tan directa como usted: tengo dos ofertas guardadas en el cajón desde hace meses. No las he respondido porque creo en este equipo. Pero creer tiene fecha de caducidad.": "assets/audio/story167-5d524ee8f9e1b2b970b3.mp3", "paco:Recibido. Y créeme, lo voy a tener muy en cuenta.": "assets/audio/story167-f8e0877e6b6839b9eb7b.mp3", "paco:Luna, ¿tienes diez minutos? Es algo que prefiero contarte yo antes de que llegue por otros cauces.": "assets/audio/story167-033ec55108f20f13cf7d.mp3", "luna:Cuéntame.": "assets/audio/story167-e72cc0baf48dd122ddee.mp3", "paco:Me han hecho una oferta. De la competencia. Buena, la verdad.": "assets/audio/story167-7c1d5359b01038a1c249.mp3", "luna:Ya. ¿Y vienes a despedirte o a negociar? Porque una cosa la haces con Recursos Humanos y la otra, conmigo.": "assets/audio/story167-93805fcc7fd1e3813744.mp3", "paco:Si quisiera irme, ya estaría escribiendo el correo. Vengo porque llevo seis años aquí y porque quiero saber si mi sitio sigue siendo aquí.": "assets/audio/story167-145de6df96cd21742d56.mp3", "luna:Eso es una respuesta bonita. También es la respuesta de quien quiere una contraoferta. No me ofende, ojo; me parece legítimo. Pero hablemos claro: ¿qué te falta aquí que allí te sobra?": "assets/audio/story167-c8392d4abac0b91116c4.mp3", "paco:Dos cosas. El sueldo, un treinta por ciento. Y liderar el equipo nuevo que están montando. Aquí hago el trabajo de líder sin el título ni el sueldo desde hace dos años.": "assets/audio/story167-2446d9b661bc816924e2.mp3", "luna:Lo del título te lo debo, es verdad. Lo del sueldo, un treinta por ciento no puedo dártelo mañana. Puedo darte el título este mes y una revisión salarial seria en enero, con números por escrito.": "assets/audio/story167-38cec54dffebbe8daba3.mp3", "paco:¿Y quién me garantiza a mí que enero no vaya a ser como la última vez, cuando la revisión se quedó en agua de borrajas?": "assets/audio/story167-253b63051dfead3d1de0.mp3", "luna:Que esta vez te doy el título primero, que eso sí está en mi mano y no se desdice. Y que si en enero el número no te convence, yo misma te escribo la recomendación para donde quieras ir. Eso no te lo ofrece nadie.": "assets/audio/story167-392bc764f22c30f089fc.mp3", "paco:¿Sabes que tu oferta es tan buena que casi me desarma?": "assets/audio/story167-99bc7aeeefb1bab7fbb9.mp3", "luna:Es que no te quiero convencido, Paco. Te quiero con los ojos abiertos. Si te quedas, te quedas sabiendo lo que tienes. Y si te vas, que te vayas bien, que la vida da muchas vueltas y prefiero que nos veamos otra vez en buenos términos.": "assets/audio/story167-3db24e1adc0188a1de87.mp3", "paco:Vale. Dame el lunes para pensarlo. El título, mientras tanto, lo acepto desde ya.": "assets/audio/story167-a6f1de039e5eaee5c156.mp3", "paco:Bueno, ya que estáis todos, mamá, papá... tenemos algo que contaros. Nos vamos a vivir fuera. A Chile.": "assets/audio/story167-cfe18cc64048db541b25.mp3", "luna:Me ha salido un puesto allí. Es una oportunidad que no se da dos veces.": "assets/audio/story167-95a0ef073aee93336df4.mp3", "paco:Mamá, di algo.": "assets/audio/story167-7668573b333216eeea7a.mp3", "luna:Es normal que necesiten un momento.": "assets/audio/story167-0845ee0c2885bc720e10.mp3", "paco:Un momento sí. Silencio total, no.": "assets/audio/story167-3ef57667f1ad6ca3e0d8.mp3", "luna:Paco, tranquilo.": "assets/audio/story167-8215e19bf349bf5de7f6.mp3", "paco:Es que ya sé lo que viene: que si estamos locos, que si los nietos, que si aquí tienes todo. Llevamos meses pensándolo, no es un capricho.": "assets/audio/story167-bfcb8fa835f0413a25c4.mp3", "luna:Y aun así, es su derecho llevarse una sorpresa. Nosotros tuvimos meses; ellos han tenido diez segundos.": "assets/audio/story167-8973489815fbb75cc19b.mp3", "paco:Tienes razón. Perdón. Es que... yo también estoy asustado, ¿sabes? Y cuando me asusto me pongo a la defensiva.": "assets/audio/story167-da42f63f078b8ebfbaab.mp3", "luna:Pues diles eso. Diles que estás asustado y que aun así lo vas a hacer. Eso lo entiende cualquier madre mejor que un discurso.": "assets/audio/story167-ba971efcba76ca0dd284.mp3", "paco:Mamá... estoy asustado. Y aun así quiero ir. Y necesito que no me lo pongas más difícil, porque me cuesta lo mío ya.": "assets/audio/story167-51a9fadba5228c965b35.mp3", "luna:Y yo os prometo que, por muy lejos que esté Chile (que no está en la luna, aunque lo parezca), habrá vuelos y videollamadas.": "assets/audio/story167-d9adb9b3d109f2020baa.mp3", "paco:Bueno, mamá, ahora sí: ¿qué dices?": "assets/audio/story167-4ab9677c6937a03e19c5.mp3", "paco:Gracias por aceptar verme. No sabía si vendrías.": "assets/audio/story167-c4714666e78a19e49608.mp3", "luna:Yo tampoco sabía si vendría. Y aquí estoy.": "assets/audio/story167-40839ea9255403e82baf.mp3", "paco:Te debo una conversación desde hace seis años. Lo de aquella noche, lo que dije delante de todos...": "assets/audio/story167-dcf58a0e25df604d7fc2.mp3", "luna:No hace falta que lo repitas. Me acuerdo palabra por palabra. Ese es el problema de las palabras así: quien las dice las olvida; quien las oye las archiva.": "assets/audio/story167-cdb5375b71443a91c8ae.mp3", "paco:No las he olvidado. Las he llevado todos estos años. Que es distinto.": "assets/audio/story167-4f49db9bc04319d4b312.mp3", "luna:¿Y a qué debo el honor, después de seis años?": "assets/audio/story167-af136d0de2c623b4530d.mp3", "paco:A que estuve a punto de escribirte veinte veces y las veinte borré el mensaje. Y a que el mes pasado me enteré de lo de tu padre, y pensé: si mañana te pasara algo, me quedaría con esto dentro para siempre.": "assets/audio/story167-e1651b26b99eef5b26e0.mp3", "luna:Así que vienes por ti. Para quitarte el peso.": "assets/audio/story167-edc2c48d60b0ad120efb.mp3", "paco:Vengo por mí, sí. Quien te dice que se disculpa solo por el otro, miente. Pero vengo también por ti, aunque no tengas por qué creértelo hoy.": "assets/audio/story167-0e64cebf62bbc6bf7aa5.mp3", "luna:Esa es la primera cosa honesta que me has dicho en años.": "assets/audio/story167-784d17af17e40ad59b2b.mp3", "paco:No te pido que lo dejes atrás, que sería pedir demasiado. Ni que volvamos a ser lo que éramos. Te pido diez minutos de vez en cuando. Un café como este. Sin promesas.": "assets/audio/story167-27108310796d33f5de90.mp3", "luna:¿Sabes qué es lo curioso? Que si me hubieras pedido perdón hace seis años, no te lo habría dado. Estaba demasiado enfadada para perdonar y demasiado orgullosa para admitir que te echaba de menos.": "assets/audio/story167-edd3a03b72f01645a041.mp3", "paco:¿Y ahora?": "assets/audio/story167-557b9ecc56ee71b85d44.mp3", "luna:Ahora estoy cansada de llevarlo. Que no es lo mismo que perdonarte, ojo. Pero es un sitio donde se puede empezar.": "assets/audio/story167-4489c76233b84d79a457.mp3", "paco:Me basta. De verdad, me basta.": "assets/audio/story167-0155d3be4da6ed7f8ecb.mp3", "luna:Buenas tardes, ¿qué necesita?": "assets/audio/story167-273a9430404db4921b6b.mp3", "paco:Buenas. Estoy resfriado desde ayer.": "assets/audio/story167-acff0e1807391556fed9.mp3", "luna:¿Qué síntomas tiene?": "assets/audio/story167-b53e8648c9a2efb2bb97.mp3", "paco:Me duele la garganta y tengo tos.": "assets/audio/story167-8436434c67be278c1ccf.mp3", "luna:¿Tiene fiebre?": "assets/audio/story167-d543779a634c8391ed12.mp3", "paco:No, fiebre no tengo.": "assets/audio/story167-f7143d145075ffb83b3a.mp3", "luna:Vale. Le doy un jarabe para la tos y pastillas para la garganta.": "assets/audio/story167-bf65d597cce4e8d944f7.mp3", "paco:¿Cómo se toman?": "assets/audio/story167-0ccc0da384eb7738ed8c.mp3", "luna:El jarabe y las pastillas, como pone en el prospecto. Cualquier duda, me pregunta.": "assets/audio/story167-7461849120e25109c15a.mp3", "paco:¿Y cuándo me voy a encontrar mejor?": "assets/audio/story167-83414ddecd52eef98f21.mp3", "luna:Depende. Si los síntomas empeoran o no mejora, vaya al médico.": "assets/audio/story167-d50aed1f18dcea0f0090.mp3", "paco:Muy bien. ¿Cuánto es todo?": "assets/audio/story167-6c601e168b753d4f710d.mp3", "luna:Doce euros con sesenta.": "assets/audio/story167-63caecf36d636c7d3b45.mp3", "paco:Aquí tiene. Gracias.": "assets/audio/story167-2ce098944a1bb2135f3b.mp3","luna:Buenos días, quiero cancelar mi suscripción al gimnasio.":"assets/audio/story167-b0ba24450e8b486dd4a5.mp3","paco:Claro. ¿Puedo preguntarle el motivo?":"assets/audio/story167-09b1131058c96dd0b2ee.mp3","luna:Casi no tengo tiempo y hace meses que no vengo.":"assets/audio/story167-eef9499a1e8d1d893705.mp3","paco:Lo entiendo. Podemos congelar la cuota durante unos meses si lo prefiere.":"assets/audio/story167-b36b6a092578d1db4565.mp3","luna:¿Y cuánto costaría congelarla?":"assets/audio/story167-35421fa3e39cfd73d989.mp3","paco:Solo una pequeña parte de lo que paga ahora.":"assets/audio/story167-fc3837ff902613225567.mp3","luna:Aun así, prefiero cancelar. ¿Tengo que pagar alguna penalización?":"assets/audio/story167-4918949d696e1e6be2a3.mp3","paco:No, si avisa con tiempo. Y usted lo hace hoy, así que la baja será efectiva el mes que viene.":"assets/audio/story167-7420c88a11430b60dea2.mp3","luna:Perfecto. ¿Necesito firmar algo?":"assets/audio/story167-06bd2ac5ed59de9e9312.mp3","paco:Sí, este formulario. Y tiene que devolver la tarjeta de acceso.":"assets/audio/story167-b63e3e413c6d82a7e233.mp3","luna:Aquí la tiene. Muchas gracias por su ayuda.":"assets/audio/story167-2d09a215f194cc32e6c3.mp3","paco:A usted. Si cambia de opinión, será bienvenida.":"assets/audio/story167-bd9d1a9e82aa8632cb2b.mp3","luna:Buenos días. Tenía reservada la sala de reuniones, pero hay otro equipo dentro.":"assets/audio/story167-a92524d723bbef86ca13.mp3","paco:Vaya, lo siento. Déjeme comprobar el sistema.":"assets/audio/story167-9a265b5c91da7a865183.mp3","paco:Efectivamente, hay un error: la reserva aparece duplicada.":"assets/audio/story167-0f3b30430511034ea001.mp3","luna:Es la tercera vez este mes. Mi equipo lleva media hora esperando.":"assets/audio/story167-45aeca8b44dbc444beed.mp3","paco:Entiendo su enfado. Puedo ofrecerle la sala pequeña de la planta baja ahora mismo.":"assets/audio/story167-9ad3bcde76f8f29975e0.mp3","luna:Es demasiado pequeña. Somos un equipo grande y necesitamos el proyector.":"assets/audio/story167-000ed8b50d4d87cd4ee0.mp3","paco:En ese caso, la sala grande quedará libre dentro de un cuarto de hora.":"assets/audio/story167-ad0262e0411f73bfe8d6.mp3","luna:Está bien, esperaremos. Pero quiero que quede constancia de la queja por escrito.":"assets/audio/story167-a2f6c519eb394c397293.mp3","paco:Por supuesto. Le enviaré un correo para que lo confirme, y avisaré al responsable del sistema.":"assets/audio/story167-bf50434760d07e697222.mp3","luna:Se lo agradezco. Y que no vuelva a ocurrir.":"assets/audio/story167-26c1b669b5372eef6fde.mp3","paco:Haré todo lo posible para que no se repita.":"assets/audio/story167-03e93ff8d39887abb3b2.mp3","luna:¿Tiene un momento? Quería plantearle una propuesta sobre mi horario.":"assets/audio/story167-fdc6ef078dad2762e901.mp3","paco:Claro, adelante. Cuénteme.":"assets/audio/story167-e05078a5e47442b9a4fd.mp3","luna:Desde que cambió el equipo, paso mucho tiempo en desplazamientos. Me gustaría teletrabajar algunos días por semana.":"assets/audio/story167-deb91ed684053297b878.mp3","paco:Lo entiendo, pero la dirección se ha mostrado reticente a ampliar el teletrabajo.":"assets/audio/story167-cdc0a836e88b28c21a0d.mp3","luna:Lo sé. Por eso he preparado un informe con los resultados de los últimos meses, para demostrar que mi rendimiento no se ve afectado.":"assets/audio/story167-bdeb03080ec1aa42b891.mp3","paco:Aprecio la iniciativa. ¿Y cómo garantizaría la coordinación con el resto del equipo?":"assets/audio/story167-10e154bdb57c969f4250.mp3","luna:Estaría disponible en las reuniones clave y mantendría abiertos los canales de comunicación durante toda la jornada.":"assets/audio/story167-a18e4225fe3189a42d70.mp3","paco:No me opongo, pero necesito el visto bueno de recursos humanos.":"assets/audio/story167-1b54d3d2f50d9f4a35d3.mp3","luna:¿Podría presentarles la propuesta junto conmigo? Así evitaríamos malentendidos.":"assets/audio/story167-0254e595b08e161ead23.mp3","paco:De acuerdo. Propongo un periodo de prueba de unos meses y, si funciona, lo formalizamos.":"assets/audio/story167-1b2cc736df89a3475ea0.mp3","luna:Me parece razonable. Gracias por escucharme.":"assets/audio/story167-3785c98785b84a5ce96e.mp3","paco:Enhorabuena por el premio. Imagino que no se lo esperaba.":"assets/audio/story167-188da3137a2ffa5c37a7.mp3","luna:Para nada. Llevaba años escribiendo en la sombra, y de repente todo el mundo quiere entrevistarme.":"assets/audio/story167-48b759d4bb1630a81570.mp3","paco:¿Le abruma tanta atención?":"assets/audio/story167-030a25f3b09e40d23ff3.mp3","luna:Un poco. Agradezco el reconocimiento, pero me inquieta que se hable más de mí que de la novela.":"assets/audio/story167-6148730aa47c9cd6b82c.mp3","paco:Es el precio de la notoriedad, supongo. ¿Cree que el premio cambiará su manera de escribir?":"assets/audio/story167-5029b96d28aaeea3fc96.mp3","luna:Ojalá que no. Temo caer en la tentación de escribir pensando en complacer al jurado.":"assets/audio/story167-2a59fcb369db6969bd49.mp3","paco:Algunos críticos sostienen que la novela es deliberadamente ambigua. ¿Está de acuerdo?":"assets/audio/story167-0a614cebd2eb9f626cc7.mp3","luna:Más bien la considero honesta: la vida rara vez ofrece finales cerrados, y no veía por qué la ficción debía hacerlo.":"assets/audio/story167-9112d1741c20a9f382ec.mp3","paco:Una postura valiente, sobre todo en un mercado que premia lo previsible.":"assets/audio/story167-0f6e27aa3030de327550.mp3","luna:Quizá, aunque confío en que los lectores agradezcan que no se les subestime.":"assets/audio/story167-3b04805366fbcc7014dd.mp3"});
Object.assign(AUDIO_CAST_MAP,{"luna:Buenos días, busco unos pantalones.": "assets/audio/story167-1cb84f193f186f687811.mp3", "paco:¿Qué talla usa?": "assets/audio/story167-bee0c3aa192e4a014600.mp3", "luna:No sé. Normalmente llevo la talla mediana.": "assets/audio/story167-8a6665d1f352b02724d9.mp3", "paco:Estos son muy bonitos. ¿Le gusta el color azul?": "assets/audio/story167-8a2892a5beeb3eea03af.mp3", "luna:Sí, me gusta mucho. ¿Puedo probarme los pantalones?": "assets/audio/story167-53d6d5ae45b076449a03.mp3", "paco:Claro. El probador está al fondo, a la derecha.": "assets/audio/story167-f144a6d30753d91ed31c.mp3", "luna:Me quedan un poco grandes. ¿Tiene una talla más pequeña?": "assets/audio/story167-efa4bccc452a4e7e0a1b.mp3", "paco:Sí, aquí tiene la talla pequeña.": "assets/audio/story167-ca81b56148c6c39e2197.mp3", "luna:Perfecto, ahora están bien. ¿Cuánto cuestan?": "assets/audio/story167-95611ca2987228bfbd5d.mp3", "paco:Veinticinco euros. Puede pagar en la caja, allí.": "assets/audio/story167-eed37b512b0f9907230d.mp3", "luna:Buenas tardes, quiero un billete para Valencia, por favor.": "assets/audio/story167-e1bab75f1cfe662693e3.mp3", "paco:¿Para qué día?": "assets/audio/story167-e36d6ddfa2d1037b874e.mp3", "luna:Para mañana por la mañana.": "assets/audio/story167-1fea36b4388c8e41a6a6.mp3", "paco:Hay un tren a las ocho y otro a las diez.": "assets/audio/story167-97785a92bd6049113544.mp3", "luna:Prefiero el de las ocho. ¿Cuánto dura el viaje?": "assets/audio/story167-e25c0b7b7fd00299fe35.mp3", "paco:Dos horas y media, más o menos.": "assets/audio/story167-3923b8bc3d8575657a52.mp3", "luna:Muy bien. ¿Cuánto cuesta el billete?": "assets/audio/story167-584babe091339c557f55.mp3", "paco:Treinta euros. ¿Ida y vuelta?": "assets/audio/story167-24d41f0f67dc7b05869b.mp3", "luna:No, solo de ida. ¿De qué vía sale el tren?": "assets/audio/story167-63b45d2389bdebf49055.mp3", "paco:De la vía cuatro. Venga un poco antes, por favor.": "assets/audio/story167-84ec9698c6a84de965fc.mp3", "paco:Buenos días. ¿Es usted alumna nueva?": "assets/audio/story167-2e5ef6f3995232a56637.mp3", "luna:Sí, hoy es mi primera clase.": "assets/audio/story167-04ce1d1f0d04bb167fe6.mp3", "paco:Bienvenida. Me llamo Paco y soy el profesor. ¿Cómo se llama usted?": "assets/audio/story167-a4e5c16bcbde043f867a.mp3", "luna:Me llamo Luna. Soy de Egipto, pero vivo aquí.": "assets/audio/story167-1bbf2baf3f5d42732a10.mp3", "paco:¿Habla un poco de español?": "assets/audio/story167-252efe794b981a346cd7.mp3", "luna:Sí, un poco. Estudio en casa todos los días.": "assets/audio/story167-a95641497e1b74bba860.mp3", "paco:Muy bien. En clase hablamos solo en español.": "assets/audio/story167-40030385e75c2dffb3a1.mp3", "luna:¿Hay deberes para mañana?": "assets/audio/story167-bc0d41a034df228f59e6.mp3", "paco:Sí, una página del libro. Y necesita un cuaderno.": "assets/audio/story167-bed4e9408ef602e3974c.mp3", "luna:De acuerdo. Muchas gracias, profesor.": "assets/audio/story167-fa5cde904b6acc3f5f53.mp3", "luna:Hola, quiero alquilar una bicicleta.": "assets/audio/story167-5e23bcc8dd62b10ff79f.mp3", "paco:¿Por cuánto tiempo?": "assets/audio/story167-97efdc1d7d5f63b70796.mp3", "luna:Dos horas, por favor.": "assets/audio/story167-60a1e5f2f193a55dc6ca.mp3", "paco:Son cinco euros. Necesito su documento de identidad.": "assets/audio/story167-4b66c3737979720b44e9.mp3", "luna:Aquí está. ¿Hay un camino bonito cerca?": "assets/audio/story167-a0ef3307b6f5bf103c07.mp3", "paco:Sí, el parque está muy cerca. Puede ir por esta calle.": "assets/audio/story167-4fb6dd4cba54f274a0d0.mp3", "luna:¿Y dónde dejo la bicicleta cuando vuelvo?": "assets/audio/story167-d867018655f76f4bdc0d.mp3", "paco:Aquí mismo, delante de la tienda.": "assets/audio/story167-54bcb8dba976bcef1f41.mp3", "luna:Vale. ¿La bicicleta tiene luces?": "assets/audio/story167-e155c5d9d75131874e69.mp3", "paco:Sí, y también un candado. El casco es obligatorio.": "assets/audio/story167-32c0ff885d0d15b24bfd.mp3", "paco:Sí, dígame.": "assets/audio/story167-bbf0d3c8c624b3eb2348.mp3", "luna:Hola, Paco, soy Luna. ¿Cómo estás?": "assets/audio/story167-061b754e7f2c2b2577ff.mp3", "paco:Muy bien, gracias. ¿Y tú?": "assets/audio/story167-8b8bfd66b18b671478e3.mp3", "luna:Bien. El sábado cocino en casa. ¿Quieres venir a cenar?": "assets/audio/story167-e8496f6cd661909ccbe9.mp3", "paco:Me encanta. ¿A qué hora?": "assets/audio/story167-67ce1634a6278a7eaeb8.mp3", "luna:A las nueve. Vivo cerca del parque, en la calle Mayor.": "assets/audio/story167-73d106e1a9bfe7510708.mp3", "paco:Perfecto. ¿Puedo llevar algo?": "assets/audio/story167-155a768f8a407e7afd24.mp3", "luna:Sí, una botella de agua, por favor.": "assets/audio/story167-021df213f8c43926227c.mp3", "paco:Vale. ¿Y quién más viene?": "assets/audio/story167-e85b76b4e52fffa3c924.mp3", "luna:Solo nosotros dos. Mi hermana está de viaje.": "assets/audio/story167-923f65fe0f024bedf26b.mp3", "luna:Buenas tardes. ¿Tiene hora libre?": "assets/audio/story167-7f3125ca12cd01a2c689.mp3", "paco:Sí, ahora mismo. ¿Qué quiere hacer?": "assets/audio/story167-cc1120f11d8f1e29d3b0.mp3", "luna:Quiero cortar el pelo, pero no muy corto.": "assets/audio/story167-c7765b7875114b704bae.mp3", "paco:De acuerdo. ¿Lo quiere lavar también?": "assets/audio/story167-888fc11eca7d22e8a3fb.mp3", "luna:Sí, por favor. Mañana tengo una fiesta.": "assets/audio/story167-e82f3de282e84dd533bf.mp3", "paco:Qué bien. ¿Una boda?": "assets/audio/story167-95df0595b3a2a2448bec.mp3", "luna:No, es el cumpleaños de una amiga.": "assets/audio/story167-f93a51895442235bc254.mp3", "paco:Ya está. ¿Le gusta?": "assets/audio/story167-07524a7c08fed744a698.mp3", "luna:Me gusta mucho. ¿Cuánto es?": "assets/audio/story167-245eebfc1d7b63305502.mp3", "paco:Quince euros.": "assets/audio/story167-88ff7112f33af2d319f7.mp3", "paco:Pase, pase. Esta es la sala.": "assets/audio/story167-9ecee9eca68008b6d16a.mp3", "luna:Es más grande. Pensé que era más pequeño. ¿Cuánto es el alquiler?": "assets/audio/story167-f717df82ab37645bdba9.mp3", "paco:Seiscientos euros al mes, con los gastos incluidos.": "assets/audio/story167-73d17d9828eb8e2fc2d4.mp3", "luna:No está mal. He visto pisos más caros en este barrio.": "assets/audio/story167-ef1855c8f198b5781a95.mp3", "paco:El piso está libre desde el mes pasado. La inquilina anterior se fue a otra ciudad.": "assets/audio/story167-30b4b9f13de704a84e4f.mp3", "luna:¿Y el contrato es por un año?": "assets/audio/story167-13cb0d915cf215f4035e.mp3", "paco:Sí, un año, y luego podemos renovarlo.": "assets/audio/story167-f5368f4bf9a2baef34a2.mp3", "luna:Trabajo en una oficina cerca de aquí, así que me viene muy bien.": "assets/audio/story167-812a3b3e2fba45f4e735.mp3", "paco:Perfecto. ¿Vive sola?": "assets/audio/story167-e6818233b634e266da44.mp3", "luna:Sí, sola. ¿Puedo ver la cocina?": "assets/audio/story167-fbb9e1b81b14d68829cf.mp3", "paco:Claro, está al fondo. La nevera es nueva.": "assets/audio/story167-eee1cd6aed812fcc8aa9.mp3", "luna:Me gusta mucho. Voy a pensarlo esta noche y mañana le llamo.": "assets/audio/story167-28206c75b8c21be1d6be.mp3", "luna:Buenos días. He comprado estos auriculares aquí la semana pasada y no funcionan.": "assets/audio/story167-cd4a2be8cafdbe5e38ba.mp3", "paco:¿Qué les pasa exactamente?": "assets/audio/story167-4a13950145ae3caa7a02.mp3", "luna:El auricular derecho no suena. Lo he probado con dos móviles.": "assets/audio/story167-f6743c7e0595bd182c09.mp3", "paco:¿Tiene el recibo?": "assets/audio/story167-ba3faf0f279c66edadd7.mp3", "luna:Sí, aquí está. También he traído la caja.": "assets/audio/story167-7f696ee5952d90ebebff.mp3", "paco:Gracias. Puedo devolverle el dinero o cambiarle el producto. ¿Qué prefiere?": "assets/audio/story167-06d88424d5ca211e2d62.mp3", "luna:Prefiero unos iguales, si los tienen.": "assets/audio/story167-c8d601fb76a5a7295072.mp3", "paco:Voy a mirar en el almacén. Un momento, por favor.": "assets/audio/story167-39252c28f33b2bc802b2.mp3", "paco:Lo siento, de ese modelo no queda ninguno. Llegarán el jueves.": "assets/audio/story167-5083f1667dc471eca2ae.mp3", "luna:Entonces prefiero el dinero. No puedo esperar hasta el jueves.": "assets/audio/story167-0d14ed7ac12a3ab19f4c.mp3", "paco:De acuerdo. Firme aquí y el dinero vuelve a su tarjeta en dos días.": "assets/audio/story167-07ee3adaa5dddb44cd1a.mp3", "luna:Muchas gracias. Ha sido muy amable.": "assets/audio/story167-35b3008bf1860a4fcbb8.mp3", "paco:¡Cuántas cajas! ¿Dónde las pongo?": "assets/audio/story167-be9506eb23f548dacc65.mp3", "luna:En el salón, por favor. Allí hay más sitio.": "assets/audio/story167-c80329926cdcee0ab176.mp3", "paco:Vale. ¿Has traído el sofá tú sola?": "assets/audio/story167-81069e558e3c98b31fcb.mp3", "luna:No, mis vecinos me ayudaron esta mañana. Han sido muy amables.": "assets/audio/story167-4c4e98aa70f8b10a4270.mp3", "paco:Me alegro. ¿Y la cama ya está montada?": "assets/audio/story167-a79a31ef527c9e920208.mp3", "luna:Todavía no. Voy a montarla esta tarde.": "assets/audio/story167-88f3365b51650ba0d93e.mp3", "paco:Te ayudo, si quieres. He montado muchas camas en mi vida.": "assets/audio/story167-a235bd1adb115c0aa21f.mp3", "luna:Gracias, Paco. ¿Tienes hambre? He comprado pizza.": "assets/audio/story167-977b926a2b6a98c58fc5.mp3", "paco:Mucho. No he comido nada desde las ocho.": "assets/audio/story167-04b5abcc1003dbc9ac50.mp3", "luna:Come algo mientras yo abro las cajas.": "assets/audio/story167-d39e32eae8a64c62c761.mp3", "paco:Está muy bien esta cocina. ¿Es nueva?": "assets/audio/story167-d642e4eaa7d12c9bdf50.mp3", "luna:Sí, la cambiaron el año pasado. Por eso elegí este piso.": "assets/audio/story167-eed8d742d658b86eefe5.mp3", "luna:Buenos días. He perdido mi móvil esta mañana en el café.": "assets/audio/story167-be192fbd235f5bf90fa4.mp3", "paco:¿En qué café ha estado?": "assets/audio/story167-c9e672286aea6f9791af.mp3", "luna:En el que está al lado de la plaza, el de la esquina.": "assets/audio/story167-31bbd6b519f5c6daac0c.mp3", "paco:¿Cómo es el móvil?": "assets/audio/story167-99e8f4f5ce7ee11f0d7a.mp3", "luna:Es negro y tiene una funda azul. También tiene una pegatina en la parte de atrás.": "assets/audio/story167-ca07e18267df9f816e2c.mp3", "paco:Un momento. Alguien trajo un móvil hace una hora.": "assets/audio/story167-fd44c91dbd5799c7c1c2.mp3", "luna:¿Y está aquí?": "assets/audio/story167-869e4a5ecf20cbbe651c.mp3", "paco:Sí. ¿Quiere llamar a su número desde aquí?": "assets/audio/story167-26ce0ff42092004cc914.mp3", "luna:Sí, gracias. Lo tengo apuntado en un papel.": "assets/audio/story167-ec517b7e2839c858bf15.mp3", "paco:Marque y si suena dentro, es suyo.": "assets/audio/story167-52c4f4d8f66930f02024.mp3", "luna:¡Suena! Es mi móvil. Muchas gracias.": "assets/audio/story167-09958e0a9c513c464ec1.mp3", "paco:De nada. La próxima vez, escriba su nombre en la funda.": "assets/audio/story167-143c319a6ba78ab6257a.mp3", "paco:Restaurante La Plaza, buenas tardes.": "assets/audio/story167-eee21497cc615d203df8.mp3", "luna:Hola, quería reservar una mesa para el viernes por la noche.": "assets/audio/story167-42d1847e8cf8b9cfb3a8.mp3", "paco:¿Para cuántas personas?": "assets/audio/story167-96a1013ca98bd432c6fe.mp3", "luna:Para seis. Es el cumpleaños de una amiga.": "assets/audio/story167-9d8161c1f5679276dc42.mp3", "paco:¿A qué hora prefiere?": "assets/audio/story167-1060ee46ff9ff8ebb249.mp3", "luna:A las nueve, si es posible. Hemos quedado todos a esa hora.": "assets/audio/story167-23a7eb5f1e6c057a8020.mp3", "paco:A las nueve estamos llenos. ¿Les va bien a las nueve y media?": "assets/audio/story167-95c201e63365a58a01ea.mp3", "luna:Sí, no hay problema. ¿Podemos estar en la terraza?": "assets/audio/story167-bff4b90526a859654a6c.mp3", "paco:Si no llueve, sí. En abril todavía hace fresco por la noche.": "assets/audio/story167-e88e36cd5153b7b3be4d.mp3", "luna:Entiendo. ¿Hay menú para grupos?": "assets/audio/story167-4a97e21e144c5455f1f7.mp3", "paco:Sí, lo hemos preparado este mes. Traeré pastel al final, si quiere.": "assets/audio/story167-0b195f6f375225b13fbc.mp3", "luna:¡Qué bien! Entonces la reserva es para seis a las nueve y media.": "assets/audio/story167-a92d6f7fa4bfc21c67b9.mp3", "paco:Buenos días, siéntese, por favor. ¿Es usted Luna?": "assets/audio/story167-482710d60bd636b355ac.mp3", "luna:Sí, buenos días. Gracias por recibirme.": "assets/audio/story167-b58bcf0fb5d66ad4d806.mp3", "paco:¿Ha trabajado antes en un bar o en un restaurante?": "assets/audio/story167-7411ada2c7b3534b22e8.mp3", "luna:Sí, he trabajado dos años en una cafetería en El Cairo.": "assets/audio/story167-39703630cee1c181edb5.mp3", "paco:¿Y por qué ha venido a España?": "assets/audio/story167-4da6bfa7a9c4920c1cd9.mp3", "luna:Vine a estudiar español y ahora busco trabajo.": "assets/audio/story167-df54afd4a84ec800c0fc.mp3", "paco:¿Cuántos idiomas habla?": "assets/audio/story167-0759bfcc651cbc184dd4.mp3", "luna:Hablo árabe, inglés y un poco de español.": "assets/audio/story167-ff43ecd67883b16e8e5a.mp3", "paco:Muy bien. El trabajo es de martes a domingo, por la mañana.": "assets/audio/story167-0be365b2a16860dde645.mp3", "luna:¿Puedo trabajar los sábados por la tarde también?": "assets/audio/story167-8ba1ee2a0d844df9bfe0.mp3", "paco:Sí, los sábados tenemos mucho trabajo.": "assets/audio/story167-6217b14d4a8885ee3bad.mp3", "paco:Voy a hablar con mi socio y mañana le digo algo.": "assets/audio/story167-425d6bd1b30b31c435f2.mp3", "luna:Perfecto. Muchas gracias por su tiempo.": "assets/audio/story167-fb9566d6afa5e8da9bd3.mp3", "paco:Banco Delta, buenos días. ¿En qué puedo ayudarle?": "assets/audio/story167-4ff2593ffd51134e0a27.mp3", "luna:Buenos días. Mi tarjeta no funciona desde ayer. No puedo pagar nada.": "assets/audio/story167-686e2f02ed5dadf56f55.mp3", "paco:¿Le aparece algún mensaje cuando intenta pagar?": "assets/audio/story167-294f7dc8a4b031b7b36a.mp3", "luna:Sí, dice que la operación no está permitida.": "assets/audio/story167-bf8ceba71909942b8cb3.mp3", "paco:Un momento. Veo que el sistema ha bloqueado la tarjeta por seguridad.": "assets/audio/story167-13f8df1ea0b29814eab8.mp3", "luna:¿Por qué? Yo no he hecho nada raro.": "assets/audio/story167-cf9ef99a9571702687dc.mp3", "paco:Ayer hubo un intento de compra en otro país. El banco lo detectó y bloqueó la tarjeta.": "assets/audio/story167-0550c2be043370317e36.mp3", "luna:¡Qué susto! A esa hora yo estaba en casa.": "assets/audio/story167-df752e6ba2c000d21e32.mp3", "paco:Entonces alguien tiene los datos de su tarjeta. Vamos a cancelarla y a enviarle una nueva.": "assets/audio/story167-1cb13504221d0d54ca15.mp3", "luna:¿Y cuánto tarda en llegar?": "assets/audio/story167-2e5f94cda73f48bfde3d.mp3", "paco:Unos cinco días laborables. Mientras tanto, puede sacar dinero en la oficina con su documento.": "assets/audio/story167-264ff6b90eb69f98f9f2.mp3", "luna:Voy a necesitar dinero el viernes. ¿Es posible hoy mismo?": "assets/audio/story167-843e2551b16bc5c0e0de.mp3", "paco:Sí, ahora le preparo una autorización. Y no comparta sus datos por teléfono ni por correo.": "assets/audio/story167-a21da4b40019a4775aa5.mp3", "luna:Lo tendré en cuenta. Muchas gracias.": "assets/audio/story167-091ee6907e54a6badad2.mp3", "luna:Buenas noches. Me he quedado fuera de casa y no tengo llaves.": "assets/audio/story167-c52be166080419f327eb.mp3", "paco:¿Dónde está ahora?": "assets/audio/story167-ad29d891d140f918cf4d.mp3", "luna:En la puerta del edificio, en la calle Mayor. Necesito que venga alguien.": "assets/audio/story167-7e47459489b3960da1fe.mp3", "paco:Puedo estar allí en media hora, pero esta noche la salida cuesta más.": "assets/audio/story167-92869907bffe405406e4.mp3", "luna:¿Cuánto cuesta?": "assets/audio/story167-f4912e317f4549e3a626.mp3", "paco:Cien euros, y si hay que cambiar la cerradura, aparte.": "assets/audio/story167-45264ef7726c45ae464e.mp3", "luna:Es mucho, pero no tengo otra opción. ¿Necesito algún documento?": "assets/audio/story167-4a1bccffca500ecad5af.mp3", "paco:Sí, el contrato de alquiler o el carné. Tengo que comprobar que la casa es suya.": "assets/audio/story167-54935842c6916347a903.mp3", "luna:Tengo el carné en el bolso. El contrato está dentro de casa.": "assets/audio/story167-16a097c669fa81721bc4.mp3", "paco:Con el carné es suficiente. ¿Tiene vecinos que puedan confirmarlo?": "assets/audio/story167-f200461c08e231f6a78a.mp3", "luna:Sí, la vecina del segundo me conoce bien.": "assets/audio/story167-43e6c41be531e5dd38ca.mp3", "paco:Perfecto. Estoy saliendo. No se mueva de la puerta.": "assets/audio/story167-d5b69c132ee9aaa99942.mp3", "luna:Aquí espero. Gracias por venir tan tarde.": "assets/audio/story167-a094b5def3af723c786a.mp3", "paco:No se preocupe. Es mi trabajo.": "assets/audio/story167-81c18d2f512d962f00fb.mp3", "luna:Buenos días. Quiero denunciar el robo de mi bicicleta.": "assets/audio/story167-8956d77bde2077e452a3.mp3", "paco:¿Cuándo ocurrió?": "assets/audio/story167-75f00de7f49f3c890478.mp3", "luna:Anoche. La dejé atada a la barandilla del portal y esta mañana ya no estaba.": "assets/audio/story167-1e171fed27d77a04b132.mp3", "paco:¿Estaba cerrada con candado?": "assets/audio/story167-b9e2ced8eacffe4f9708.mp3", "luna:Sí, con un candado de esos gruesos. Seguro que lo han cortado.": "assets/audio/story167-0a96e96ec93a21b944bc.mp3", "paco:¿Tiene la factura de compra o el número de serie?": "assets/audio/story167-5d0ec87b851bc2287538.mp3", "luna:La factura la tengo en casa. El número de serie no lo sé de memoria.": "assets/audio/story167-012094732cf2ffc7f341.mp3", "paco:Con la factura es suficiente. ¿Ha avisado al seguro?": "assets/audio/story167-e32240e98558601bf8dd.mp3", "luna:No, primero quería poner la denuncia. ¿Sirve de algo?": "assets/audio/story167-e5eacf73db74016cb730.mp3", "paco:A veces sí. Si aparece la bicicleta, la llamamos. Y muchas compañías piden la denuncia para pagar.": "assets/audio/story167-a65414a4df6ffd828a0c.mp3", "luna:Entiendo. ¿Tengo que pagar algo por la denuncia?": "assets/audio/story167-96c5145d829cda7940df.mp3", "paco:No, es gratis. Firme aquí y le doy una copia.": "assets/audio/story167-b159578d18f0a08f99de.mp3", "luna:Gracias. La próxima vez la dejaré dentro del portal.": "assets/audio/story167-f3845aa3a2336e3f2cda.mp3", "paco:Buena idea. Y use un candado mejor.": "assets/audio/story167-c69f3ea4387ebd3ddc72.mp3", "luna:Hola, señor Ruiz. Soy Luna, trabajé en su equipo hace tres años.": "assets/audio/story167-651da6476a0218805fe6.mp3", "paco:Luna, claro que me acuerdo. ¿Cómo estás?": "assets/audio/story167-21775a7c4c76755909c2.mp3", "luna:Bien, gracias. Le llamo porque estoy buscando trabajo y me piden una recomendación.": "assets/audio/story167-e3f8688d46dbd8e43cc6.mp3", "paco:¿Y quieres que la escriba yo?": "assets/audio/story167-5845bd5b0fb8fa861c66.mp3", "luna:Si no le importa. Trabajamos juntos dos años y conoce bien mi trabajo.": "assets/audio/story167-d1309f33254b654b2573.mp3", "paco:Me acuerdo de que llevabas muy bien los proyectos difíciles.": "assets/audio/story167-288999b290c9d626aca2.mp3", "luna:Gracias. La empresa nueva pide una carta firmada y un teléfono de contacto.": "assets/audio/story167-2315ad9adc609e7d55e6.mp3", "paco:Puedo escribirla esta semana. ¿Para cuándo la necesitas?": "assets/audio/story167-a9e5ee2705b71e54290f.mp3", "luna:Antes del viernes, si es posible. La entrevista es el lunes.": "assets/audio/story167-61919c14e1960e95ad79.mp3", "paco:No hay problema. ¿Quieres que mencione también el curso de formación?": "assets/audio/story167-43a6991ba6714e84c941.mp3", "luna:Sí, por favor. Fue importante para mí.": "assets/audio/story167-5b6348aa598adf19efb4.mp3", "paco:De acuerdo. Envíame por correo los datos del puesto y lo preparo.": "assets/audio/story167-fe9fc6644e64b7b7e325.mp3", "luna:Se lo mando hoy mismo. Muchas gracias, de verdad.": "assets/audio/story167-7575c53a09951d30b78b.mp3", "paco:No hay de qué. Me alegra saber de ti.": "assets/audio/story167-b8ceafa7a0b1304f167f.mp3", "luna:Buenas tardes. Vengo a devolver el coche. Todo ha ido bien.": "assets/audio/story167-7be10f7d00fe81da89de.mp3", "paco:Déjeme ver. Un momento, por favor.": "assets/audio/story167-be72f37f2628c7be5582.mp3", "paco:Aquí hay un golpe en la puerta derecha. ¿Lo ha visto?": "assets/audio/story167-8413abab9d38539cd064.mp3", "luna:No. Cuando lo alquilé no estaba. Estoy segura.": "assets/audio/story167-1195f302ff2896d19e0e.mp3", "paco:En el contrato pone que el coche estaba sin daños.": "assets/audio/story167-eacdf5fe7d03caf0a938.mp3", "luna:Ya, pero yo no lo he golpeado. Solo lo he aparcado en la calle.": "assets/audio/story167-7d69da3bf872131142e7.mp3", "paco:Entonces alguien lo ha golpeado mientras estaba aparcado.": "assets/audio/story167-e98b02a154ab66bdd189.mp3", "luna:¿Y tengo que pagarlo yo? Yo contraté el seguro completo.": "assets/audio/story167-df9c103786bd7b6a45af.mp3", "paco:Con el seguro completo, usted paga solo una parte. Vamos a ver la cantidad.": "assets/audio/story167-5641fb98a195001c22ad.mp3", "luna:Quiero ver las fotos que hice antes de salir con el coche.": "assets/audio/story167-89a6d3ec7113e8e4371d.mp3", "paco:Perfecto. Si el golpe ya estaba, no paga nada.": "assets/audio/story167-f1ee2c5d0bb0eecc4dc6.mp3", "luna:Aquí están. Mire la fecha: son del día que recogí el coche.": "assets/audio/story167-071af2a8733bbe138998.mp3", "paco:Tiene razón. El golpe ya estaba. Le pido disculpas por la molestia.": "assets/audio/story167-4d5e38f3761546ea977f.mp3", "luna:Gracias. La próxima vez haré más fotos todavía.": "assets/audio/story167-21dd565990e59a953066.mp3", "luna:Buenas tardes. Mi vuelo a Roma de las seis está cancelado y nadie me ha avisado.": "assets/audio/story167-693aee24125c693042ef.mp3", "paco:Lo siento mucho. Ha sido por un problema técnico del avión.": "assets/audio/story167-b0840dfc9bcc4d2ce744.mp3", "luna:Tengo una boda el sábado. Necesito llegar mañana como sea.": "assets/audio/story167-93e9252adf2512c3b349.mp3", "paco:Puedo ofrecerle un vuelo mañana a primera hora, con escala en Barcelona.": "assets/audio/story167-a1ac09a750e26ff4b22b.mp3", "luna:¿A qué hora llega a Roma?": "assets/audio/story167-fb778a66abad3d4f84fa.mp3", "paco:A las dos de la tarde, así que llegará a tiempo para la boda.": "assets/audio/story167-14fcb80bd6c52db164ac.mp3", "luna:De acuerdo, pero quiero saber qué derechos tengo. He leído que me corresponde una compensación.": "assets/audio/story167-0366a9f8229587d5dc63.mp3", "paco:Sí, en este caso le corresponde, porque no le avisamos con tiempo.": "assets/audio/story167-3e88ef52d58302703ffb.mp3", "luna:¿Y cómo la pido? ¿La tramitan ustedes o tengo que hacerlo yo?": "assets/audio/story167-e565f21b238a16e1cf8b.mp3", "paco:Puede pedirla por la página web. También le pagamos el hotel de esta noche y la cena.": "assets/audio/story167-72002857c71025f65d8b.mp3", "luna:Eso esperaba, porque no tengo dónde dormir.": "assets/audio/story167-d732f8db00c06e11f82d.mp3", "paco:Le doy un papel con el número de reserva del hotel. Está cerca del aeropuerto.": "assets/audio/story167-fbe5bcc91e4ae1582885.mp3", "luna:Muy bien. ¿Y si el vuelo de mañana también se cancela?": "assets/audio/story167-75100ff4297e92eb683c.mp3", "paco:Entonces le buscaríamos otra compañía. No la dejaremos aquí.": "assets/audio/story167-9aeebf652e43460e7571.mp3", "paco:Luna, necesito hablarte de algo y me da vergüenza.": "assets/audio/story167-66a951eadb6ab1ae3fc7.mp3", "luna:Dime, Paco. ¿Qué pasa?": "assets/audio/story167-bb4d42c58246f8be70c5.mp3", "paco:Me han pedido dejar el piso donde vivo y necesito tres mil euros para la entrada de otro.": "assets/audio/story167-c50eed26cca8ee80994b.mp3", "luna:¿Tres mil? Es mucho dinero.": "assets/audio/story167-8842b1ea482e7bfac227.mp3", "paco:Lo sé. Te lo devolvería en un año, poco a poco. Te lo prometo.": "assets/audio/story167-a7cfeb95cf57f4351eb8.mp3", "luna:No es que no quiera ayudarte, pero nunca he prestado una cantidad así.": "assets/audio/story167-7d945f8dfaef75145781.mp3", "paco:Lo entiendo. Si no puedes, lo entenderé de verdad.": "assets/audio/story167-3178c6073d0b6c94f44e.mp3", "luna:Déjame pensar. ¿Tienes trabajo fijo ahora?": "assets/audio/story167-5f6dd8b426f4a3470bca.mp3", "paco:Sí, en el almacén. Llevo allí ocho meses.": "assets/audio/story167-20d83fd409b831abd43d.mp3", "luna:Entonces puedo prestarte una parte, no los tres mil. Y quiero un papel firmado.": "assets/audio/story167-09e14c852be1d7f37737.mp3", "paco:Claro, lo que quieras. ¿Qué cantidad puedes?": "assets/audio/story167-3dbe6858c9be97651ecf.mp3", "luna:Mil quinientos, y me los devuelves en diez meses. Sin prisa, pero sin olvidarlo.": "assets/audio/story167-10bc2efd2495e8d5b967.mp3", "paco:Me parece justo. Gracias, de verdad. No sabes lo que significa para mí.": "assets/audio/story167-49620e20f15c92578df6.mp3", "luna:Solo espero que no tengamos que hablar de esto otra vez.": "assets/audio/story167-3920b988d3afee82d501.mp3", "paco:He visto el anuncio de tu coche. ¿Sigue disponible?": "assets/audio/story167-685c6a6cf8d08e4cbf6c.mp3", "luna:Sí, todavía no lo he vendido.": "assets/audio/story167-db1d52fb271ff9c4930a.mp3", "paco:¿Cuántos kilómetros tiene?": "assets/audio/story167-8342bc2d6d68d8ac7989.mp3", "luna:Ciento veinte mil, más o menos. Pero está bien cuidado y las revisiones están al día.": "assets/audio/story167-2f75fd15cbcf8eb04eea.mp3", "paco:El precio del anuncio me parece alto. He visto coches parecidos más baratos.": "assets/audio/story167-e065ba35bb428928324a.mp3", "luna:Puedo bajar un poco, pero no mucho. Le he puesto neumáticos nuevos este año.": "assets/audio/story167-4323506dad95e3bf1a6b.mp3", "paco:¿Aceptarías cuatro mil quinientos?": "assets/audio/story167-91530622106d269b9d28.mp3", "luna:Pedía cinco mil. Cuatro mil ochocientos es lo mínimo.": "assets/audio/story167-7d2062bf6393dccfa18b.mp3", "paco:De acuerdo. Pero tengo que pagarte en dos veces: la mitad ahora y la otra mitad el mes que viene.": "assets/audio/story167-92b6b89cb7768eb76ab1.mp3", "luna:Eso no me convence. Si el coche cambia de dueño, el papeleo se hace una sola vez.": "assets/audio/story167-82a27c6abb5ca55eea00.mp3", "paco:Puedo dejarte una señal ahora y el resto cuando firmemos.": "assets/audio/story167-e8f548195eadbef90fc3.mp3", "luna:Así está bien. ¿Puedes venir el jueves al taller para que lo revise un mecánico?": "assets/audio/story167-9bb3617274ea4b638df5.mp3", "paco:Me parece razonable. Si todo está bien, cerramos el trato.": "assets/audio/story167-d467a7808846f910ccfc.mp3", "luna:Perfecto. Te mando la dirección del taller.": "assets/audio/story167-720e95e94e58441dca46.mp3", "luna:Profesor, quería preguntarle una cosa. Estoy pensando en presentarme al examen oficial de español.": "assets/audio/story167-7d5004fa12270b30dd4d.mp3", "paco:Me parece una buena idea. ¿Para cuándo sería?": "assets/audio/story167-a31ca29f4cbd260e1f90.mp3", "luna:La inscripción termina el viernes y el examen es en mayo.": "assets/audio/story167-b5e047cd037a11a8fe7d.mp3", "paco:Entonces tienes tres meses para prepararte. ¿Cómo te sientes con la expresión escrita?": "assets/audio/story167-85f147ae15bcfd48b99b.mp3", "luna:Ahí es donde tengo más problemas. Hablo bastante bien, pero cuando escribo cometo muchos errores.": "assets/audio/story167-44fad2d6f33be4b61df3.mp3", "paco:Eso se arregla con práctica. ¿Y la comprensión auditiva?": "assets/audio/story167-63e24cd36f1fcdabcad1.mp3", "luna:Me da miedo. A veces no entiendo nada cuando hablan rápido.": "assets/audio/story167-fdeed605a85989223a1d.mp3", "paco:En el examen hablan despacio y repiten dos veces. No es tan difícil como parece.": "assets/audio/story167-134c674acb9f039e2ad8.mp3", "luna:¿Y si no lo apruebo? Habré gastado el dinero para nada.": "assets/audio/story167-21fa66e789cd17663807.mp3", "paco:Aunque no lo apruebes, habrás practicado y sabrás en qué fallas. Puedes repetirlo en noviembre.": "assets/audio/story167-92d74cf3598c9741c8f9.mp3", "luna:Tiene razón. ¿Me ayudaría a corregir mis textos una vez por semana?": "assets/audio/story167-65c574de48f14f5743ab.mp3", "paco:Claro. Y te recomiendo que escribas un diario en español, aunque sea corto.": "assets/audio/story167-356a3ea0333c22a37a06.mp3", "luna:Voy a inscribirme hoy mismo antes de que se me olvide.": "assets/audio/story167-608cd5bb986592e9371b.mp3", "paco:Buena decisión. Y no te preocupes demasiado por el resultado.": "assets/audio/story167-3fbb83381f583180f219.mp3", "luna:Buenos días. Le llamo porque ha aparecido humedad en el dormitorio.": "assets/audio/story167-cf96e1bed914f7801e3c.mp3", "paco:¿Humedad? ¿Está segura de que no es una gotera pequeña?": "assets/audio/story167-bcb5480a9ba4b17fc701.mp3", "luna:Es una mancha grande en la pared y la ropa del armario huele mal.": "assets/audio/story167-088f586bf54f7adc3556.mp3", "paco:Puede que el problema venga de la terraza del vecino de arriba.": "assets/audio/story167-3f639db67e515ad01fc1.mp3", "luna:No lo sé, pero tiene que venir alguien a mirarlo. Llevo dos semanas esperando.": "assets/audio/story167-47cd9ed0c2ff7fd3b8c6.mp3", "paco:Le mandé un mensaje la semana pasada y no me contestó.": "assets/audio/story167-cecdd7add103c6600030.mp3", "luna:No me llegó nada. Revise el número, por favor.": "assets/audio/story167-7e3b0de80678953950cf.mp3", "paco:Tiene razón, lo he enviado a un número antiguo. Le pido disculpas.": "assets/audio/story167-e0ab9d158497ca3cce22.mp3", "luna:De acuerdo. ¿Cuándo puede venir un técnico?": "assets/audio/story167-74ac6509b1b7d682e5ce.mp3", "paco:El jueves por la mañana. Si hay que romper la pared, tardará dos o tres días.": "assets/audio/story167-9b9d8c43a0b404a6442f.mp3", "luna:Y mientras tanto, ¿puedo pagar menos de alquiler? La habitación no se puede usar.": "assets/audio/story167-e365fabe0608efe02068.mp3", "paco:Vamos a ver el informe del técnico. Si el problema es del edificio, le descontamos esos días.": "assets/audio/story167-a37a90ef6d1da7005da4.mp3", "luna:Me parece justo. Le mando las fotos por correo ahora mismo.": "assets/audio/story167-7f3174ee2f05d9f75791.mp3", "paco:Perfecto. Y si empeora, avíseme enseguida.": "assets/audio/story167-c00ef1a8c5f965b2e146.mp3"});
